pub(super) const EVENT_HANDLER: u32 = 1 << 12;
/// In `browser_fn`.
pub(super) const BROWSER_FN: u32 = 1 << 13;
/// In `dom_fn`.
pub(super) const DOM_FN: u32 = 1 << 14;
/// A word some pattern at a name's start in code keys on.
pub(super) const KW: u32 = 1 << 15;
/// A word `support-objects` keys on after a `.`, beyond its lists.
pub(super) const MEMBER: u32 = 1 << 16;
/// A word of `literal`'s, with [`KW`].
pub(super) const LITERAL: u32 = 1 << 17;
/// `await`, `delete`, `void` or `new`, with [`KW`].
pub(super) const OP_WORD: u32 = 1 << 18;
/// The bits a pattern at a name's start reads: a name without them is plain.
pub(super) const AT_NAME: u32 = BUILTIN_CLASS | SUPPORT_FN | DOM_VAR | DOM_CLASS | NODE_CLASS | KW;
/// The bits a pattern at a `.` before a name reads: a member without them is plain.
pub(super) const AT_DOT: u32 = DOM_CONST | DOM_PROP | EVENT_HANDLER | BROWSER_FN | DOM_FN | MEMBER;

