/// The longest word: longer ones are none of them.
const LONGEST: usize = 33;

const SLOT_BITS: u32 = 12;
const SLOTS: usize = 1 << SLOT_BITS;

/// A hash of fixed cost: the first and last four bytes (or the bytes of a shorter word) and the
/// length, multiplied, the top bits a slot (C++'s).
const fn hash(w: &[u8]) -> usize {
    let n = w.len();
    let x = if n >= 4 {
        let a = u32::from_le_bytes([w[0], w[1], w[2], w[3]]) as u64;
        let z = u32::from_le_bytes([w[n - 4], w[n - 3], w[n - 2], w[n - 1]]) as u64;
        a | z << 32
    } else {
        let mut x = 0u64;
        let mut i = 0;
        while i < n {
            x |= (w[i] as u64) << (8 * i);
            i += 1;
        }
        x
    };
    ((x ^ n as u64).wrapping_mul(0x9e37_79b9_7f4a_7c15) >> (64 - SLOT_BITS)) as usize
}

/// [`ENTRIES`] by their hash, open addressing: an entry's index plus 1 a slot, 0 for none.
static TABLE: [u16; SLOTS] = {
    let mut t = [0u16; SLOTS];
    let mut i = 0;
    while i < ENTRIES.len() {
        let mut k = hash(ENTRIES[i].0);
        while t[k] != 0 {
            k = (k + 1) % SLOTS;
        }
        t[k] = i as u16 + 1;
        i += 1;
    }
    t
};

/// Word `w`'s bits, 0 for a word in no list.
#[inline]
pub(super) fn class(w: &[u8]) -> u32 {
    if w.is_empty() || w.len() > LONGEST {
        return 0;
    }
    let mut k = hash(w);
    loop {
        let i = usize::from(TABLE[k]);
        if i == 0 {
            return 0;
        }
        let (e, bits) = ENTRIES[i - 1];
        if e == w {
            return bits;
        }
        k = (k + 1) % SLOTS;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_finds_its_words() {
        for &(w, bits) in &ENTRIES {
            assert_eq!(class(w), bits, "{}", String::from_utf8_lossy(w));
        }
        assert_eq!(class(b"Array"), BUILTIN_CLASS);
        assert_eq!(class(b"const"), KW);
        assert_eq!(class(b"Function"), BUILTIN_CLASS);
        assert_eq!(class(b"foo"), 0);
        assert_eq!(class(b"Arrays"), 0);
    }
}
